// Flutter service worker - generated by Flutter build system
// This file enables PWA caching and offline support.
// On BrightSign, this file should not be registered (service workers are not supported).
const CACHE_NAME = "flutter-app-cache";
const RESOURCES = {
  "/": "3948271650",
  "/index.html": "3948271650",
  "/flutter.js": "3948271650",
  "/main.dart.js": "3948271650",
  "/assets/AssetManifest.json": "3948271650",
  "/assets/FontManifest.json": "3948271650"
};

self.addEventListener("activate", function(event) {
  event.waitUntil(
    caches.keys().then(function(cacheName) {
      return Promise.all(
        cacheName.map(function(key) {
          if (key !== CACHE_NAME) {
            return caches.delete(key);
          }
        })
      );
    })
  );
});

self.addEventListener("install", function(event) {
  self.skipWaiting();
  return null;
});

self.addEventListener("fetch", function(event) {
  var origin = self.location.origin;
  var key = event.request.url.substring(origin.length + 1);
  if (RESOURCES[key]) {
    event.respondWith(caches.open(CACHE_NAME).then(function(cache) {
      return cache.match(event.request).then(function(cachedResponse) {
        return cachedResponse || fetch(event.request).then(function(response) {
          cache.put(event.request, response.clone());
          return response;
        });
      });
    }));
  }
});
